def clean_string(s):
 for a,b in [('\u00c3\u00a9','\u00e9'),('\u00c3\u00a9','\u00e9'),('\u00e2\u20ac\u2122','\u2019'),('\u00e2\u20ac\u201c','\u2013'),('\u00e2\u2020\u2019','\u2192')]:s=s.replace(a,b)
 return s
def clean(d):
 if isinstance(d,str):return clean_string(d)
 if isinstance(d,list):return [clean(x) for x in d]
 if isinstance(d,dict):return {k:clean(x) for k,x in d.items()}
 return d
def save(n,d): (p/n).write_text(json.dumps(clean(d),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
